#!/usr/bin/env node
// scripts/gen-tux.js — compile mods/tux/tokens.json roles and thresholds into mods/tux/palette.ts.
//
// A hooks module imports only code files, never .json. palette.ts is generated. Do not edit it.
//
//   node scripts/gen-tux.js           write mods/tux/palette.ts
//   node scripts/gen-tux.js --check   exit 1 when palette.ts drifts from tokens.json
//
// exit codes: 0 ok · 1 check failed · 2 usage / unreadable input

'use strict';
const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const jsonPath = path.join(root, 'mods', 'tux', 'tokens.json');
const outPath = path.join(root, 'mods', 'tux', 'palette.ts');

function fail(why) {
  process.stderr.write(`gen-tux: ${why}\n`);
  process.exit(2);
}

function readTokens() {
  let raw;
  try {
    raw = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
  } catch (e) {
    fail(`cannot read mods/tux/tokens.json: ${e.message}`);
  }
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) fail('tokens.json is not an object');
  if (typeof raw.roles !== 'object' || raw.roles === null || Array.isArray(raw.roles)) fail('tokens.roles must be an object');
  const roles = Object.entries(raw.roles);
  if (roles.length === 0) fail('tokens.roles is empty');
  for (const [k, v] of roles) {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(k)) fail(`role name is not an identifier: ${k}`);
    if (typeof v !== 'string' || v.length === 0) fail(`roles.${k} must be a non-empty string`);
  }
  if (typeof raw.thresholds !== 'object' || raw.thresholds === null || Array.isArray(raw.thresholds)) fail('tokens.thresholds must be an object');
  if (typeof raw.thresholds.warn !== 'number' || typeof raw.thresholds.critical !== 'number') fail('thresholds.warn and thresholds.critical must be numbers');
  return raw;
}

function render(tokens) {
  const keys = Object.keys(tokens.roles);
  const union = keys.map((k) => JSON.stringify(k)).join(' | ');
  const entries = keys.map((k) => `  ${k}: ${JSON.stringify(tokens.roles[k])},`).join('\n');
  return '// GENERATED by scripts/gen-tux.js from mods/tux/tokens.json. Do not edit.\n'
    + '//   node scripts/gen-tux.js\n'
    + '// A hooks module imports only code files, never .json. PALETTE is tokens.roles; THRESHOLDS is tokens.thresholds.\n\n'
    + "import type { ThemeKey } from '../live/model.ts'\n\n"
    + `export type PaletteRole = ${union}\n`
    + `export const PALETTE: Record<PaletteRole, ThemeKey> = {\n${entries}\n}\n`
    + `export const THRESHOLDS = { warn: ${tokens.thresholds.warn}, critical: ${tokens.thresholds.critical} } as const\n`;
}

function main(argv) {
  const tokens = readTokens();
  const generated = render(tokens);
  if (argv.includes('--check')) {
    let onDisk = null;
    try { onDisk = fs.readFileSync(outPath, 'utf8'); } catch (_e) { /* none */ }
    if (onDisk !== generated) {
      process.stderr.write('gen-tux: palette.ts is out of date: run `node scripts/gen-tux.js`\n');
      return 1;
    }
    process.stdout.write('gen-tux: ok\n');
    return 0;
  }
  fs.writeFileSync(outPath, generated);
  process.stdout.write('gen-tux: wrote mods/tux/palette.ts\n');
  return 0;
}

if (require.main === module) process.exit(main(process.argv.slice(2)));
module.exports = { render, readTokens };
